<?php
declare(strict_types=1);

/**
 * install_mrl_team_redesign.php
 *
 * VERSION: v008
 * LAST MODIFIED: 8/27/2026 7:26:58 pm
 *
 * PURPOSE:
 * Fix the Admin-menu loader bug using the exact uploaded Live v007 baseline,
 * while performing a conservative cleanup of obsolete redesign-era debug code.
 *
 * EXPECTED INPUT:
 * - team_redesign.php VERSION: v007
 * - mrl_team/admin_team_page_content.php VERSION: v003
 * - mrl_team/mrl_team_page_content.json with all four panel keys
 *
 * OUTPUT:
 * - team_redesign.php VERSION: v008
 *
 * SAFETY:
 * - Exact SHA-256 baseline check for team_redesign.php.
 * - Exact SHA-256 baseline check for Content Manager v003.
 * - JSON must be valid and contain non-empty Admin panel item arrays.
 * - User-edited JSON is never rewritten by this installer.
 * - Production team.php and profile.php are hash-verified unchanged.
 * - Current team_redesign.php is backed up before replacement.
 *
 * CHANGELOG:
 *
 * v008 (8/27/2026 7:26:58 pm)
 * - FIX: team_redesign.php now loads all four JSON panels.
 * - CLEANUP: Removes obsolete Connected DB diagnostic/environment URL helpers.
 * - CLEANUP: Consolidates panel fallback/merge logic into one four-panel schema.
 * - PRESERVE: Content Manager, saved JSON/order, themes, profile, charts,
 *             pick/scoring behavior, production team.php and profile.php.
 */

date_default_timezone_set('America/New_York');

const EXPECTED_TEAM_SHA256 = 'd0a4a326bc3db89de27090eec71b59a22084521356bcb1e79bce22839334bc61';
const EXPECTED_MANAGER_SHA256 = 'fe2a8c9050f6b5c6055975b3f211dd3ca0b57363ff5c6b225d74cf5a02bf4bbb';

$base = __DIR__;
$teamPath = $base . '/team_redesign.php';
$managerPath = $base . '/mrl_team/admin_team_page_content.php';
$jsonPath = $base . '/mrl_team/mrl_team_page_content.json';
$prodTeamPath = $base . '/team.php';
$prodProfilePath = $base . '/profile.php';

function h(string $v): string
{
    return htmlspecialchars($v, ENT_QUOTES, 'UTF-8');
}

function status_row(string $label, bool $ok, string $detail = ''): void
{
    echo '<tr><td>' . h($label) . '</td><td class="' . ($ok ? 'ok' : 'bad') . '">'
        . ($ok ? 'PASS' : 'FAIL') . '</td><td>' . h($detail) . '</td></tr>';
}

function atomic_write(string $path, string $data): bool
{
    $tmp = $path . '.tmp_' . bin2hex(random_bytes(4));

    if (file_put_contents($tmp, $data, LOCK_EX) === false) {
        return false;
    }

    if (!@rename($tmp, $path)) {
        @unlink($tmp);
        return false;
    }

    return true;
}

$replacement = base64_decode('', true);
$replacementOk = is_string($replacement)
    && strpos($replacement, 'VERSION: v008') !== false
    && strpos($replacement, 'foreach ($teamPageContentPanelKeys as $panelKey)') !== false;

$teamExists = is_file($teamPath);
$managerExists = is_file($managerPath);
$jsonExists = is_file($jsonPath);

$teamHash = $teamExists ? hash_file('sha256', $teamPath) : '';
$managerHash = $managerExists ? hash_file('sha256', $managerPath) : '';

$teamBaselineOk = $teamExists
    && $teamHash === EXPECTED_TEAM_SHA256
    && strpos((string)file_get_contents($teamPath), 'VERSION: v007') !== false;

$managerBaselineOk = $managerExists
    && $managerHash === EXPECTED_MANAGER_SHA256
    && strpos((string)file_get_contents($managerPath), 'VERSION: v003') !== false;

$jsonData = null;
$jsonOk = false;
$panelCounts = [];
$requiredPanels = [
    'admin_league_panel',
    'admin_hosting_panel',
    'league_panel',
    'team_panel',
];

if ($jsonExists) {
    $raw = file_get_contents($jsonPath);
    $decoded = is_string($raw) ? json_decode($raw, true) : null;

    if (is_array($decoded)) {
        $jsonData = $decoded;
        $jsonOk = true;

        foreach ($requiredPanels as $panelKey) {
            $items = $decoded[$panelKey]['items'] ?? null;
            $count = is_array($items) ? count($items) : -1;
            $panelCounts[$panelKey] = $count;

            if ($count < 0) {
                $jsonOk = false;
            }
        }

        // The two Admin panels must contain items because the user has already
        // edited/reordered them in Content Manager.
        if (($panelCounts['admin_league_panel'] ?? 0) < 1
            || ($panelCounts['admin_hosting_panel'] ?? 0) < 1) {
            $jsonOk = false;
        }
    }
}

$prodTeamExists = is_file($prodTeamPath);
$prodProfileExists = is_file($prodProfilePath);
$prodTeamBefore = $prodTeamExists ? hash_file('sha256', $prodTeamPath) : '';
$prodProfileBefore = $prodProfileExists ? hash_file('sha256', $prodProfilePath) : '';

$apply = isset($_POST['apply']) && $_POST['apply'] === '1';
$messages = [];
$success = false;

if ($apply && $replacementOk && $teamBaselineOk && $managerBaselineOk && $jsonOk
    && $prodTeamExists && $prodProfileExists) {

    $backupDir = $base . '/_migration_backups/team_redesign_v008_' . date('Ymd_His');

    $ok = (is_dir($backupDir) || mkdir($backupDir, 0755, true));

    if (!$ok) {
        $messages[] = 'Could not create backup directory.';
    } elseif (!copy($teamPath, $backupDir . '/team_redesign.php')) {
        $ok = false;
        $messages[] = 'Could not back up team_redesign.php.';
    } else {
        $messages[] = 'Backed up exact v007 team_redesign.php.';
    }

    if ($ok) {
        if (!atomic_write($teamPath, $replacement)) {
            $ok = false;
            $messages[] = 'Could not install team_redesign.php v008.';
        } else {
            $messages[] = 'Installed clean team_redesign.php v008.';
        }
    }

    if ($ok) {
        $installed = (string)file_get_contents($teamPath);

        $postChecks = [
            'v008 header' => strpos($installed, 'VERSION: v008') !== false,
            'four-panel JSON loader' => strpos($installed, 'foreach ($teamPageContentPanelKeys as $panelKey)') !== false,
            'Admin League fallback' => strpos($installed, "'admin_league_panel' => [") !== false,
            'Admin Hosting fallback' => strpos($installed, "'admin_hosting_panel' => [") !== false,
            'obsolete DB banner removed' => strpos($installed, 'Connected DBs:') === false,
            'obsolete DB helper removed' => strpos($installed, 'teampage_get_current_db_names') === false,
        ];

        foreach ($postChecks as $label => $passed) {
            $messages[] = ($passed ? 'PASS: ' : 'FAIL: ') . $label;
            if (!$passed) {
                $ok = false;
            }
        }
    }

    $prodTeamAfter = $prodTeamExists ? hash_file('sha256', $prodTeamPath) : '';
    $prodProfileAfter = $prodProfileExists ? hash_file('sha256', $prodProfilePath) : '';

    $prodTeamUntouched = $prodTeamBefore !== '' && $prodTeamBefore === $prodTeamAfter;
    $prodProfileUntouched = $prodProfileBefore !== '' && $prodProfileBefore === $prodProfileAfter;

    $messages[] = $prodTeamUntouched
        ? 'Verified production team.php unchanged.'
        : 'ERROR: production team.php changed.';

    $messages[] = $prodProfileUntouched
        ? 'Verified production profile.php unchanged.'
        : 'ERROR: production profile.php changed.';

    $messages[] = 'Saved menu JSON was read-only and left untouched.';
    $messages[] = 'Content Manager v003 was read-only and left untouched.';

    $success = $ok && $prodTeamUntouched && $prodProfileUntouched;
}
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>MRL Team Redesign Installer v008</title>
<style>
*{box-sizing:border-box}
html{background:#111}
body{margin:0;color:#eee;font-family:Tahoma,Verdana,Segoe UI,sans-serif}
.wrap{width:94%;max-width:1200px;margin:20px auto}
.card{background:#202020;border:1px solid #555;border-radius:14px;padding:20px;margin-bottom:16px}
h1,h2{color:#efc982}
table{width:100%;border-collapse:collapse}
td{padding:9px;border-bottom:1px solid #444;vertical-align:top}
.ok{color:#61e493}
.bad{color:#ff7777}
button{padding:11px 20px;background:#1466c9;color:#fff;border:1px solid #5a7fb5;border-radius:9px;font-weight:800;cursor:pointer}
a,code{color:#76cfff}
li{line-height:1.45;margin-bottom:5px}
</style>
</head>
<body>
<div class="wrap">

<div class="card">
<h1>MRL Team Redesign Installer v008</h1>
<p>This uses the exact <code>team_redesign.php v007</code> you uploaded as the baseline. This is no longer a guessed patch.</p>
</div>

<div class="card">
<h2>Preflight</h2>
<table>
<?php status_row('Exact uploaded team_redesign.php v007 baseline', $teamBaselineOk, $teamHash); ?>
<?php status_row('Exact uploaded Content Manager v003 baseline', $managerBaselineOk, $managerHash); ?>
<?php status_row('Four-panel JSON schema readable', $jsonOk, $jsonPath); ?>
<?php foreach ($panelCounts as $panel => $count): ?>
<?php status_row('JSON ' . $panel, $count >= 0, (string)$count . ' item(s)'); ?>
<?php endforeach; ?>
<?php status_row('v008 replacement generated', $replacementOk, 'Complete v008 file embedded; guard check corrected.'); ?>
<?php status_row('Production team.php present', $prodTeamExists, $prodTeamPath); ?>
<?php status_row('Production profile.php present', $prodProfileExists, $prodProfilePath); ?>
</table>
</div>

<?php if ($replacementOk && $teamBaselineOk && $managerBaselineOk && $jsonOk
    && $prodTeamExists && $prodProfileExists): ?>
<div class="card">
<h2>What v008 actually fixes</h2>
<ul>
<li><strong>Root cause:</strong> v007 only loaded <code>league_panel</code> and <code>team_panel</code> from JSON. The Admin panel JSON was never copied into <code>$teamPageContent</code>.</li>
<li>v008 loads all four panels from the same schema.</li>
<li>Your saved/reordered JSON is not modified.</li>
<li>The working Content Manager v003 is not modified.</li>
<li>Safe cleanup removes the old Connected DB diagnostic functions and now-unused environment URL helper code.</li>
<li>I deliberately did <strong>not</strong> aggressively rewrite the accumulated CSS in this fix; the current visual result is working and that kind of cleanup is better done after the page is functionally final.</li>
<li>Charts, picks, themes and profile behavior remain unchanged.</li>
</ul>
<?php if (!$apply): ?>
<form method="post"><input type="hidden" name="apply" value="1"><button>Install v008 Exact Fix</button></form>
<?php endif; ?>
</div>
<?php endif; ?>

<?php if ($apply): ?>
<div class="card">
<h2>Apply Result</h2>
<p class="<?php echo $success ? 'ok' : 'bad'; ?>"><strong><?php echo $success ? 'SUCCESS' : 'FAILED'; ?></strong></p>
<ul><?php foreach ($messages as $m): ?><li><?php echo h($m); ?></li><?php endforeach; ?></ul>
<?php if ($success): ?>
<p><a href="/team_redesign.php" target="_blank">Open Team Redesign v008</a></p>
<p><a href="/mrl_team/admin_team_page_content.php" target="_blank">Open Content Manager v003</a></p>
<?php endif; ?>
</div>
<?php endif; ?>

</div>
</body>
</html>
